    expect(() => value.store.prepareOwnedSessionSend({ ...value.request, idempotencyKey: randomUUID() })).toThrow("SESSION_SEND_OWNER_LIMIT");
    expect(value.store.listUnsettledMutations({ sessionId: value.session.id })).toEqual([]);
